265	app.put("/api/assets/:assetId/upload", async (c) => {
266	  const { assets } = await import("@paperclipai/db");
267	  const { eq } = await import("drizzle-orm");
268	  const { forbidden, notFound, badRequest } = await import("../../../server/src/errors.js");
269	
270	  const env = c.env;
271	  const { db } = getRouteCache(env);
272	  const deploymentMode = env.DEPLOYMENT_MODE === "local_trusted" ? "local_trusted" as const : "authenticated" as const;
273	  const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode });
274	
275	  try {
276	    const assetId = c.req.param("assetId");
277	    if (!assetId) return c.json({ error: "Missing assetId" }, 400);
278	    const assetRow = await db.select().from(assets).where(eq(assets.id, assetId)).then((rows) => rows[0] ?? null);
279	    if (!assetRow) throw notFound("Asset not found");
280	
281	    if (!actor) throw forbidden("Authentication required");
282	    if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(assetRow.companyId)) {
283	      throw forbidden("No access to this company");
284	    }
285	    if (actor.type === "agent" && actor.companyId !== assetRow.companyId) {
286	      throw forbidden("No access to this company");
287	    }
288	
289	    const body = c.req.raw.body;
290	    if (!body) throw badRequest("Empty request body");
291	    const key = `assets/${assetRow.companyId}/${assetId}`;
292	    await env.PAPERCLIP_STORAGE.put(key, body, { httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" } });
293	    return c.json({ ok: true, key });
294	  } catch (err) {
295	    if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
296	    console.error("[CF Worker] PUT /api/assets/:assetId/upload", err);
297	    return c.json({ error: "Internal Server Error" }, 500);
298	  }
299	});
