301	app.post("/api/issues/:issueId/attachments/upload", async (c) => {
302	  const { issues } = await import("@paperclipai/db");
303	  const { eq } = await import("drizzle-orm");
304	  const { forbidden, notFound, badRequest } = await import("../../../server/src/errors.js");
305	
306	  const env = c.env;
307	  const { db } = getRouteCache(env);
308	  const deploymentMode = env.DEPLOYMENT_MODE === "local_trusted" ? "local_trusted" as const : "authenticated" as const;
309	  const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode });
310	
311	  try {
312	    const issueId = c.req.param("issueId");
313	    if (!issueId) return c.json({ error: "Missing issueId" }, 400);
314	    const issueRow = await db.select({ id: issues.id, companyId: issues.companyId })
315	      .from(issues).where(eq(issues.id, issueId)).then((rows) => rows[0] ?? null);
316	    if (!issueRow) throw notFound("Issue not found");
317	
318	    if (!actor) throw forbidden("Authentication required");
319	    if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(issueRow.companyId)) {
320	      throw forbidden("No access to this company");
321	    }
322	    if (actor.type === "agent" && actor.companyId !== issueRow.companyId) {
323	      throw forbidden("No access to this company");
324	    }
325	
326	    const body = c.req.raw.body;
327	    if (!body) throw badRequest("Empty request body");
328	    const filename = (c.req.header("x-filename") ?? "attachment").replace(/[^a-zA-Z0-9._-]/g, "_");
329	    const key = `issues/${issueRow.companyId}/${issueId}/attachments/${filename}`;
330	    await env.PAPERCLIP_STORAGE.put(key, body, { httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" } });
331	    return c.json({ ok: true, key, filename });
332	  } catch (err) {
333	    if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
334	    console.error("[CF Worker] POST /api/issues/:issueId/attachments/upload", err);
335	    return c.json({ error: "Internal Server Error" }, 500);
336	  }
337	});
